// Generated by `just generate` from `src/kernel/spec-store.ts`. Edit the source and run `just generate`.
// The store of the specs: the format of `events.jsonl` and the reader of it.
// Each line after the header is one state change of a package or of a change.
// The `spec` slice, the status line, and the handoff read the store through this file.
// Only the `spec` slice writes it. The reader takes a `FileReader`, so a test needs no file on disk.

import path from "node:path";
import { SPEC_ROOT } from "./paths.ts";
import type { FileReader } from "./ports.ts";

/** The `schema` number of `events.jsonl`. Another number stops the reader. */
export const SPEC_SCHEMA = 2;

/** The `schema` key of the front matter of each Markdown file. */
export const FRONT_SCHEMA = "dotclaude-spec/2";

/** The name of the log file in the folder of a change. */
export const EVENTS_FILE = "events.jsonl";

/**
 * One state change: a package that moved to `state`, or the change itself when `package` is absent.
 * The optional keys hold the evidence of the move: the commit `sha`, the `verify` result, the review `verdict`, the `findings`, the `decision`, the `note`, and the `model`.
 */
export type StateEvent = {
  readonly at: string;
  readonly package?: string;
  readonly state: string;
  readonly sha?: string;
  readonly verify?: { readonly command: string; readonly exit: number };
  readonly verdict?: "approve" | "reject";
  readonly findings?: readonly string[];
  readonly decision?: "fix-code" | "revise-spec";
  readonly note?: string;
  readonly model?: string;
};

/** The first line of `events.jsonl`. */
export type EventsHeader = { readonly schema: typeof SPEC_SCHEMA };

/** The path of `events.jsonl` of the change `id`. */
export const eventsPath = (id: string): string =>
  path.posix.join(SPEC_ROOT, id, EVENTS_FILE);

/** The header line of a new `events.jsonl`, with its line end. */
export const eventsHeader = (): string =>
  `${JSON.stringify({ schema: SPEC_SCHEMA } satisfies EventsHeader)}\n`;

/** One line of `events.jsonl` for `event`, with its line end. */
export const eventLine = (event: StateEvent): string =>
  `${JSON.stringify(event)}\n`;

/** Parses one line of `file`, and names the file and the line when the line is not JSON. */
const parseLine = (file: string, line: number, text: string): unknown => {
  try {
    return JSON.parse(text);
  } catch {
    throw new Error(`${file}:${line}: this line is not JSON.`);
  }
};

/** True when `text` is one JSON value. */
export const isJson = (text: string): boolean => {
  try {
    JSON.parse(text);
    return true;
  } catch {
    return false;
  }
};

/**
 * The state events of the change `id` and the line of a torn last line, or null when the change has no `events.jsonl`.
 * A torn last line has no line end and is not JSON, as a crash in the middle of an append leaves it.
 * The scan skips a torn last line and gives its line number in `torn`, or null when there is none.
 * The scan throws an `Error` that names the file when the header has a `schema` other than `SPEC_SCHEMA`.
 * It throws an `Error` that names the file and the line when a line that is not torn is not JSON.
 */
export const scanEvents = async (
  files: FileReader,
  id: string,
): Promise<{
  readonly events: readonly StateEvent[];
  readonly torn: number | null;
} | null> => {
  const file = eventsPath(id);
  const text = await files.read(file);
  if (text === null) return null;
  const [head, ...rest] = text
    .split("\n")
    .map((raw, i) => ({ raw, line: i + 1 }))
    .filter(({ raw }) => raw.trim() !== "");
  const header = (
    head ? parseLine(file, head.line, head.raw) : {}
  ) as Partial<EventsHeader>;
  if (header.schema !== SPEC_SCHEMA)
    throw new Error(
      `${file} has schema ${String(header.schema)}, which this version does not read.`,
    );
  const last = rest.at(-1);
  const open = !text.endsWith("\n");
  const events: StateEvent[] = [];
  for (const entry of rest) {
    if (entry === last && open && !isJson(entry.raw))
      return { events, torn: entry.line };
    events.push(parseLine(file, entry.line, entry.raw) as StateEvent);
  }
  return { events, torn: null };
};

/**
 * The state events of the change `id`, in the order of the log, or null when the change has no `events.jsonl`.
 * The reader skips a torn last line, as `scanEvents` does, and throws the errors of `scanEvents`.
 */
export const readEvents = async (
  files: FileReader,
  id: string,
): Promise<readonly StateEvent[] | null> =>
  (await scanEvents(files, id))?.events ?? null;

/** The states that a package does not leave. */
const CLOSED: readonly string[] = ["done", "canceled"];

/** The state of each package in `events`: the last event of the package, in the order of the first event. */
export const lastStates = (
  events: readonly StateEvent[],
): Record<string, string> => {
  const states: Record<string, string> = {};
  for (const event of events)
    if (event.package !== undefined) states[event.package] = event.state;
  return states;
};

/** The id in the front matter of a package file, or null when the file has none. */
const packageId = (text: string): string | null => {
  const front = /^---\r?\n([\s\S]*?)\r?\n---/.exec(text)?.[1] ?? "";
  const id = /^id:\s*["']?([^\s"']+)["']?\s*$/m.exec(front)?.[1];
  return id ?? null;
};

/**
 * The states of the packages of the change `id`.
 * The package files in `packages/` give the set of packages, and a package with a file and no event is `planned`.
 * A state of a package with no file stays.
 * The packages of `events` come first, in the order of their first event, and then the packages that have only a file.
 */
export const packageStates = async (
  files: FileReader,
  id: string,
  events: readonly StateEvent[],
): Promise<Record<string, string>> => {
  const states = lastStates(events);
  const dir = path.posix.join(SPEC_ROOT, id, "packages");
  for (const name of (await files.list(dir))
    .filter((n) => n.endsWith(".md"))
    .sort()) {
    const text = await files.read(path.posix.join(dir, name));
    const pkg = text === null ? null : packageId(text);
    if (pkg !== null && !(pkg in states)) states[pkg] = "planned";
  }
  return states;
};

/** The done and total counts of the active change, for a segment such as `◆ 1.0.0 4/13`. A `canceled` package is not in the total. */
export type Progress = {
  readonly id: string;
  readonly done: number;
  readonly total: number;
};

/**
 * The active change and its counts: the last change, in the order of its id, that has a package which is not `done`.
 * It gives null when every change is done, or when no change has an `events.jsonl`.
 */
export const activeProgress = async (
  files: FileReader,
): Promise<Progress | null> => {
  let active: Progress | null = null;
  for (const id of (await files.list(SPEC_ROOT)).sort()) {
    const events = await readEvents(files, id);
    if (!events) continue;
    const states = Object.values(await packageStates(files, id, events)).filter(
      (state) => state !== "canceled",
    );
    const done = states.filter((state) => state === "done").length;
    if (done < states.length) active = { id, done, total: states.length };
  }
  return active;
};

/** True when `state` is a state that a package does not leave. */
export const isClosed = (state: string): boolean => CLOSED.includes(state);
